export interface ConnectorConfig {
  /** Salesforce instance URL, e.g. "na1.salesforce.com" or "mycompany.my.salesforce.com" */
  salesforceInstanceUrl: string;
  /** Bearer access token for Salesforce REST API */
  salesforceAccessToken: string;
  /** Injected fetch implementation (defaults to global fetch) */
  fetch?: typeof fetch;
}

export interface HubSpotDealWebhookPayload {
  dealId: string;
  properties: {
    domain: string;
    name: string;
  };
}

export interface SalesforceUpsertResponse {
  id: string;
  success: boolean;
  errors: unknown[];
  created: boolean;
}

export interface HandleResult {
  salesforceAccountId: string;
  created: boolean;
}

function validatePayload(payload: unknown): asserts payload is HubSpotDealWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object');
  }
  const p = payload as Record<string, unknown>;
  if (typeof p.dealId !== 'string' || !p.dealId) {
    throw new Error('Missing required field: dealId (string)');
  }
  if (!p.properties || typeof p.properties !== 'object') {
    throw new Error('Missing required field: properties (object)');
  }
  const props = p.properties as Record<string, unknown>;
  if (typeof props.domain !== 'string' || !props.domain) {
    throw new Error('Missing required field: properties.domain (string)');
  }
  if (typeof props.name !== 'string' || !props.name) {
    throw new Error('Missing required field: properties.name (string)');
  }
}

export async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload);

  const { dealId, properties } = payload;
  const { domain, name } = properties;

  const instanceUrl = config.salesforceInstanceUrl.replace(/^https?:\/\//, '').replace(/\/+$/, '');
  const url = `https://${instanceUrl}/services/data/v68.0/sobjects/Account/external_id__c/${encodeURIComponent(dealId)}`;

  const body = JSON.stringify({
    Website: domain,
    Name: name,
  });

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${config.salesforceAccessToken}`,
      'Content-Type': 'application/json',
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`Salesforce upsert failed: ${response.status} ${response.statusText} for PATCH ${url}`);
  }

  const data = (await response.json()) as SalesforceUpsertResponse;

  if (!data.success) {
    const errorMsg = Array.isArray(data.errors) && data.errors.length > 0
      ? JSON.stringify(data.errors)
      : 'Unknown error';
    throw new Error(`Salesforce upsert reported failure: ${errorMsg}`);
  }

  return {
    salesforceAccountId: data.id,
    created: data.created,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, HubSpotDealWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      salesforceInstanceUrl: 'na1.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.salesforceAccountId).toBe('001xx000003DGhpAAG');
    expect(result.created).toBe(false);
  });
});

